params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
$wt='C:\Users\Xxkan\AppData\Local\Temp\hcp-hardening-1131-a1'
$branch='agent/hcp-hardening-20260929-1131-a1'
$payloadPath='heaven-bridge/payloads/chatgpt-hcp-hardening-1129.py'
Set-Location $repo
git fetch origin --prune
if($LASTEXITCODE -ne 0){ throw 'fetch failed' }
git fetch origin '+refs/heads/heaven-bridge:refs/remotes/origin/heaven-bridge'
if($LASTEXITCODE -ne 0){ throw 'fetch heaven-bridge failed' }
if(Test-Path $wt){ git worktree remove --force $wt | Out-Null; Remove-Item -Recurse -Force $wt -ErrorAction SilentlyContinue }
git show-ref --verify --quiet "refs/heads/$branch"
if($LASTEXITCODE -eq 0){ git branch -D $branch | Out-Null }
git worktree add -b $branch $wt origin/main
if($LASTEXITCODE -ne 0){ throw 'worktree add failed' }
Set-Location $wt
$base=(git rev-parse HEAD | Out-String).Trim()
cmd /d /s /c "git show origin/heaven-bridge:$payloadPath > .hcp_patch.py"
if($LASTEXITCODE -ne 0){ throw 'failed to materialize patcher' }
python .hcp_patch.py
if($LASTEXITCODE -ne 0){ throw 'patcher failed' }
Remove-Item .hcp_patch.py -Force
git diff --check
if($LASTEXITCODE -ne 0){ throw 'git diff --check failed' }
python plugins/heaven-control-plane/verify.py
if($LASTEXITCODE -ne 0){ throw 'control-plane verify failed' }
python heaven-bridge/test_worker.py
if($LASTEXITCODE -ne 0){ throw 'bridge primary regressions failed' }
python heaven-bridge/tests/test_worker.py
if($LASTEXITCODE -ne 0){ throw 'bridge compatibility regressions failed' }
$owned=@(
 'plugins/heaven-control-plane/README.md',
 'plugins/heaven-control-plane/pyproject.toml',
 'plugins/heaven-control-plane/manifest.json',
 'plugins/heaven-control-plane/verify.py',
 'plugins/heaven-control-plane/heaven_control_plane/protocol.py',
 'plugins/heaven-control-plane/heaven_control_plane/adapters/heaven_bridge.py',
 'plugins/heaven-control-plane/tests/test_vertical_slice.py'
)
git add -- $owned
git diff --cached --check
if($LASTEXITCODE -ne 0){ throw 'staged diff check failed' }
git commit -m "plugin: harden Heaven control-plane safety contracts"
if($LASTEXITCODE -ne 0){ throw 'commit failed' }
$tries=0
while($tries -lt 5){
  $tries++
  git fetch origin main
  if($LASTEXITCODE -ne 0){ throw 'fetch main failed' }
  git merge-base --is-ancestor origin/main HEAD
  if($LASTEXITCODE -ne 0){
    git rebase origin/main
    if($LASTEXITCODE -ne 0){ git rebase --abort | Out-Null; throw 'rebase onto moving main failed' }
    python plugins/heaven-control-plane/verify.py
    if($LASTEXITCODE -ne 0){ throw 'post-rebase control-plane verify failed' }
    python heaven-bridge/test_worker.py
    if($LASTEXITCODE -ne 0){ throw 'post-rebase bridge primary regressions failed' }
    python heaven-bridge/tests/test_worker.py
    if($LASTEXITCODE -ne 0){ throw 'post-rebase bridge compatibility regressions failed' }
    git diff --check origin/main...HEAD
    if($LASTEXITCODE -ne 0){ throw 'post-rebase diff check failed' }
  }
  $final=(git rev-parse HEAD | Out-String).Trim()
  git push origin HEAD:main
  if($LASTEXITCODE -eq 0){
    git fetch origin main | Out-Null
    $remote=(git rev-parse origin/main | Out-String).Trim()
    if($remote -eq $final){
      $summary=[ordered]@{
        status='integrated'
        base_main=$base
        final_main=$final
        remote_main=$remote
        tries=$tries
        control_plane_verify='pass'
        bridge_primary='pass'
        bridge_compatibility='pass'
        version='0.1.1'
      }
      Set-Location $repo
      git worktree remove --force $wt | Out-Null
      git branch -D $branch | Out-Null
      $summary | ConvertTo-Json -Compress
      exit 0
    }
  }
}
throw "safe main push did not converge; branch=$branch head=$((git rev-parse HEAD | Out-String).Trim())"
